// Usage: node probe.mjs <casefile.json>   or   node probe.mjs --inline '<json array>'
import { spawnSync } from 'node:child_process';

const EXE = '/workspace/dataset/test11_executable';

function label(s) {
  let out = '';
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (cp >= 0x21 && cp <= 0x7e) out += ch;
    else if (cp <= 0xff) out += '\\x' + cp.toString(16).padStart(2, '0');
    else if (cp <= 0xffff) out += '\\u' + cp.toString(16).padStart(4, '0');
    else out += '\\U' + cp.toString(16).padStart(8, '0');
  }
  return out;
}

export function probe(value, { useEq = true } = {}) {
  const args = useEq ? ['--a', 'X', '--b=' + value] : ['--a', 'X', '--b', value];
  const r = spawnSync(EXE, args, { encoding: 'utf8' });
  if (r.status === 0) {
    const lines = r.stdout.split('\n');
    return { ok: true, plusOne: lines[2] };
  }
  const errLines = r.stderr.trimEnd().split('\n');
  return { ok: false, status: r.status, err: errLines[errLines.length - 1] };
}

const cases = JSON.parse(process.argv[3] ?? process.argv[2]);
for (const c of cases) {
  const value = typeof c === 'string' ? c : c.v;
  const note = typeof c === 'string' ? '' : (c.n ?? '');
  const r = probe(value);
  const res = r.ok ? 'OK   b+1=' + r.plusOne : 'FAIL ' + r.err;
  console.log(`[${label(value)}]${note ? ' (' + note + ')' : ''}  ->  ${res}`);
}

