// Test scaffolding: probe Python int(str) semantics via the reference executable.
// Usage: node intprobe.mjs '<json array of strings or {v,n}>'
import { spawnSync } from 'node:child_process';

const EXE = '/workspace/dataset/test11_executable';

function label(s) {
  let out = '';
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (cp >= 0x21 && cp <= 0x7e) out += ch;
    else if (cp === 0x20) out += '\\x20';
    else if (cp <= 0xff) out += '\\x' + cp.toString(16).padStart(2, '0');
    else if (cp <= 0xffff) out += '\\u' + cp.toString(16).padStart(4, '0');
    else out += '\\U' + cp.toString(16).padStart(8, '0');
  }
  return out;
}

function probe(value) {
  const r = spawnSync(EXE, ['--a', 'X', '--b=' + value], { encoding: 'utf8', maxBuffer: 1 << 28 });
  if (r.status === 0) {
    const lines = r.stdout.split('\n');
    return { ok: true, plusOne: lines[2] };
  }
  const errLines = r.stderr.trimEnd().split('\n');
  return { ok: false, status: r.status, err: errLines[errLines.length - 1] };
}

const cases = JSON.parse(process.argv[2]);
for (const c of cases) {
  const value = typeof c === 'string' ? c : c.v;
  const note = typeof c === 'string' ? '' : (c.n ?? '');
  const r = probe(value);
  const res = r.ok ? 'OK   b+1=' + r.plusOne : 'FAIL ' + r.err;
  console.log(`${(note ? note + ' ' : '')}[${label(value)}]  ->  ${res}`);
}

// Whitespace sweep: for each candidate code point, test ws+"7"+ws
import { spawnSync } from 'node:child_process';
const EXE = '/workspace/dataset/test11_executable';

const cps = [];
for (let i = 0x01; i <= 0x20; i++) cps.push(i);           // ASCII controls + space
for (const c of [0x7f, 0x85, 0xa0, 0x1680, 0x180e]) cps.push(c);
for (let i = 0x2000; i <= 0x200b; i++) cps.push(i);
for (const c of [0x2028, 0x2029, 0x202f, 0x205f, 0x2060, 0x3000, 0xfeff, 0x061c, 0x00ad]) cps.push(c);

function hex(cp) { return 'U+' + cp.toString(16).toUpperCase().padStart(4, '0'); }

for (const cp of cps) {
  const ws = String.fromCodePoint(cp);
  const r = spawnSync(EXE, ['--a', 'X', '--b=' + ws + '7' + ws], { encoding: 'utf8', maxBuffer: 1 << 28 });
  let verdict;
  if (r.status === 0) verdict = 'STRIPPED (b+1=' + r.stdout.split('\n')[2] + ')';
  else {
    const el = r.stderr.trimEnd().split('\n');
    verdict = 'REJECTED  ' + el[el.length - 1].replace(/^.*invalid int value: /, '');
  }
  console.log(hex(cp).padEnd(9) + ' ' + verdict);
}

