  if (cp >= 0xD800 && cp <= 0xDFFF) continue;
  if (ndRe.test(String.fromCodePoint(cp))) nd.push(cp);
}
const ranges = [];
{ let s = nd[0], p = nd[0];
  for (const c of nd.slice(1)) { if (c === p + 1) { p = c; continue; } ranges.push([s, p]); s = c; p = c; }
