  console.log('digit count      :', nd.length + 1);
  console.log('utf8 argv bytes  :', Buffer.byteLength(s, 'utf8'));
  console.log('expected b+1 head:', want.slice(0, 40) + '...' + want.slice(-20), '(len ' + want.length + ')');
